import {TYPES,WEAPONS,freeDeploy,getBattleTheatre,factionName,canDeployType,supportsCustomLoadout,isWW2,isHistorical} from './engine.js?v=0.13.0';
import {MODEL_SOURCES,PERIODS,CATEGORIES,PAYLOAD_WEIGHTS} from './modern-catalog.js?v=0.13.0';
export function createEquipmentUI({getState,modal,escape:esc,onDeploy,getSide,setSide,loadoutEditor}){
  let deploy=false,query='',country='',category='',period='',series='modern',page=0,detail=null,chosen=null,timer;
  const size=24,modern=Object.entries(TYPES).filter(([,t])=>t.model);
  const weapons=w=>Object.entries(w||{}).filter(([,n])=>n>0).map(([k,n])=>`${WEAPONS[k].short} × ${n}`).join(' / ')||'无进攻武器';
  function list(){detail=null;const state=getState(),side=getSide(),budget=side==='blue'?state.budget:state.redBudget,theatre=getBattleTheatre(state);
    const rows=Object.entries(TYPES).filter(([id,t])=>(!deploy||canDeployType(state,id,side))&&(series==='ww2'?t.era==='ww2':series==='modern'?t.model:!t.model&&t.era!=='ww2')&&(!query||`${t.aliases||''} ${t.name} ${t.desc} ${t.code}`.toLowerCase().includes(query.toLowerCase()))&&(!country||t.country===country)&&(!category||t.category===category||t.domain===category)&&(!period||t.period===period));
    page=Math.min(page,Math.max(0,Math.ceil(rows.length/size)-1));
    modal(deploy?'选择部署装备':series==='ww2'?'二战装备库':'现代装备库',`<div class="catalog-intro"><div><span class="eyebrow">MODERN ARSENAL</span><h3>${series==='ww2'?'二战舰炮、航空与水下作战':modern.length+' 个真实型号'}</h3><p>${series==='ww2'?'按双方部署点配置战列舰、巡洋舰、驱逐舰、潜艇与舰载航空队。舰艇鱼雷、深弹和补给库存有限。':'现实型号与任务定位，配合适合推演的参数。'}</p></div><button class="outline" data-equipment-lab>进入现代试验场 ↗</button></div>${deploy?`<p>选择型号查看挂载，然后在海图放置。${theatre?`${factionName(state,side)}可部署本国型号与通用岸基支援；美方 X ≤ ${theatre.anchors.blue.x.toFixed(1)}、中方 X ≥ ${theatre.anchors.red.x.toFixed(1)} 海里，保持至少 ${theatre.initialSeparationKm} 公里初始间隔。`:freeDeploy(state)?'双方可编辑，部署点相同。':'蓝方部署区 X ≤ 115 nm。'}</p>${freeDeploy(state)?`<div class="side-toggle">${['blue','red'].map(k=>`<button data-equipment-side="${k}" class="${side===k?'active':''}">${factionName(state,k)} · ${Math.floor(k==='blue'?state.budget:state.redBudget)} 点</button>`).join('')}</div>`:''}`:''}<div class="catalog-filters"><label class="catalog-search">搜索型号、国家或任务<input id="catalog-search" type="search" value="${esc(query)}" placeholder="如：F-35、反潜、中国" autocomplete="off"></label><label>装备系列<select id="catalog-series"><option value="modern" ${series==='modern'?'selected':''}>真实现代型号</option><option value="abstract" ${series==='abstract'?'selected':''}>通用／历史任务型</option><option value="ww2" ${series==='ww2'?'selected':''}>二战舰机与潜艇</option></select></label><label>任务类别<select id="catalog-category"><option value="">全部类别</option>${Object.entries(series==='modern'?CATEGORIES:{air:'航空',surface:'水面',sub:'水下',land:'岸基'}).map(([id,name])=>`<option value="${id}" ${category===id?'selected':''}>${name}</option>`).join('')}</select></label><label>国家／设计来源<select id="catalog-country" ${series==='abstract'?'disabled':''}><option value="">${deploy&&theatre?theatre.factions[side].country:'全部'}</option>${[...new Set(modern.filter(([id])=>!deploy||canDeployType(state,id,side)).map(([,t])=>t.country))].map(name=>`<option ${country===name?'selected':''}>${name}</option>`).join('')}</select></label><label>技术阶段<select id="catalog-period" ${series==='abstract'?'disabled':''}><option value="">全部阶段</option>${Object.entries(PERIODS).map(([id,name])=>`<option value="${id}" ${period===id?'selected':''}>${name}</option>`).join('')}</select></label></div><div class="catalog-count" aria-live="polite">找到 ${rows.length} 项 · ${page+1} / ${Math.max(1,Math.ceil(rows.length/size))} 页${deploy?` · ${factionName(state,side)}余 ${Math.floor(budget)} 点`:''}</div><div class="catalog-grid">${rows.slice(page*size,(page+1)*size).map(([id,t])=>`<article class="equipment-card"><div class="equipment-meta">${esc(t.country||'任务近似')} · ${esc(CATEGORIES[t.category]||({air:'航空',surface:'水面',sub:'潜艇',land:'岸基'}[t.domain]))}</div><h4>${esc(t.name)}</h4><p>${esc(t.realRole||t.desc)}</p><div class="equipment-tags"><span>${t.cost} 点${t.deck?' · 含航空队':''}</span><span>${t.domain==='air'?`${t.endurance} 分钟`:t.domain==='land'?'固定阵地':`${t.speed} kn`}</span></div><button class="outline wide" data-equipment-model="${id}">能力与${t.domain==='air'?'任务挂载':'弹库'} ↗</button></article>`).join('')||'<p class="catalog-empty">没有匹配装备，请调整筛选条件。</p>'}</div><div class="catalog-pagination"><button data-equipment-page="${page-1}" ${page===0?'disabled':''}>上一页</button><span>${rows.length?`${page*size+1}–${Math.min((page+1)*size,rows.length)}`:'0'} / ${rows.length}</span><button data-equipment-page="${page+1}" ${(page+1)*size>=rows.length?'disabled':''}>下一页</button></div><p class="help-foot">型号条目不等于各国现役完整编制；具体改批与客户配置可能不同。射程、载弹、航时、成本和命中率均为游戏参数。未模拟水雷战、登陆作战流程、完整甲板调度和战略核武器。</p>`);
    document.querySelector('#dialog').classList.add('catalog-dialog');
  }
  function model(id){clearTimeout(timer);detail=id;const t=TYPES[id],state=getState(),row=typeof chosen==='object'&&chosen?chosen:t.loadouts?.find(l=>l.id===chosen)||t.loadouts?.[0],budget=getSide()==='blue'?state.budget:state.redBudget;chosen=row?.id==='custom'?row:row?.id||null;
    const used=t.payloadSlots?Object.entries(row.weapons).reduce((n,[k,q])=>n+(PAYLOAD_WEIGHTS[k]||1)*q,0):null;
    const cells=t.vlsCells?Object.entries(t.vlsWeapons).reduce((n,[k,w])=>n+(row.weapons[k]||0)*w,0):null;
    const canDeploy=state.phase==='setup'&&!isHistorical(state),eligible=canDeployType(state,id,getSide());
    modal(t.name,`<button class="catalog-back" data-equipment-back>← 返回装备库</button><div class="equipment-meta">${esc(t.country||'任务近似')} · ${esc(PERIODS[t.period]||'通用／历史合成型')} · ${esc(t.realRole||t.name)}</div><h3 class="dialog-section-title">现实定位</h3><p>${esc(t.realNote||t.desc)}</p>${t.publicConfig?'<p class="catalog-caution">按公开配置抽象；不推定未公开性能或完整武器集成。</p>':''}<div class="model-pros"><div><strong>主要价值</strong><p>${esc(t.strengths||t.desc)}</p></div><div><strong>运用限制</strong><p>${esc(t.limitations||'需要有效航迹、适用目标和足够弹药。')}</p></div></div><h3 class="dialog-section-title">推演参数 · 游戏值</h3><div class="model-stats">${[['部署点',`${t.cost}${t.deck?'（含缩编航空队）':''}`],['最大速度',`${t.speed} kn`],['雷达标称',`${t.radar} nm`],['声呐标称',`${t.sonar} nm`],['结构值',t.hp],['续航',t.endurance?`${t.endurance} 分钟`:'场景内抽象不限航程']].map(([label,value])=>`<div><span>${label}</span><b>${value}</b></div>`).join('')}</div>${row?`<label class="control-select">${t.domain==='air'?'任务挂载':'弹库方案'}<select id="detail-loadout">${t.loadouts.map(l=>`<option value="${l.id}" ${row.id===l.id?'selected':''}>${l.name}</option>`).join('')}${row.id==='custom'?`<option value="custom" selected>${esc(row.name)}</option>`:''}</select></label>${supportsCustomLoadout(id)?`<button class="outline custom-loadout-entry" data-equipment-custom="${id}">${t.domain==='air'?'自定义挂载':'自定义弹库'} ↗</button>`:''}<div class="model-loadout"><b>${weapons(row.weapons)}</b><p>${esc(row.note)}${used!==null?` 载荷额度 ${used} / ${t.payloadSlots}。`:''}${cells!==null?` 垂发占用 ${cells} / ${t.vlsCells} 单元。`:''}${row.external?' 外挂使雷达可探测特征增加。':''}</p></div>`:`<p>${weapons(t.weapons)}</p>`}${t.deck?`<h3 class="dialog-section-title">舰载航空队 · 游戏缩编</h3><p>在空上限 ${t.deck.capacity} 架，放飞间隔 ${t.deck.cooldown} 秒；航空补给 ${t.baseSupply} 点。</p><div class="wing-list">${Object.entries(t.deck.wing).map(([key,q])=>`<span>${esc(TYPES[key].name)} × ${q}</span>`).join('')||'仅有兼容直升机着舰点，不配常驻航空队'}</div>`:''}${t.unmodeled?`<p>${esc(t.unmodeled)}</p>`:''}<div class="model-weapon-names">${Object.entries(row?.weapons||t.weapons).filter(([,n])=>n>0).map(([key,n])=>`<div><span>${esc(t.profiles[key]?.name||WEAPONS[key].name)}</span><b>× ${n}</b></div>`).join('')}</div><p class="help-foot">${esc(t.gameNote||'任务型装备的数值为游戏近似。')}</p><div class="brief-sources">${(t.sourceIds||[]).map(key=>`<a href="${MODEL_SOURCES[key].url}" target="_blank" rel="noopener noreferrer">${esc(MODEL_SOURCES[key].title)} ↗</a>`).join('')}</div><div class="model-deploy"><span>${t.cost} 部署点${deploy?` · 余 ${Math.floor(budget)} 点`:''}</span><button class="primary" data-equipment-place="${id}" ${!canDeploy||!eligible||budget<t.cost?'disabled':''}>${!canDeploy?'本战局不可部署':!eligible?`仅限${factionName(state,getSide())}装备`:budget<t.cost?'部署点不足':'部署此配置 ↗'}</button></div>`);document.querySelector('#dialog').classList.add('catalog-dialog');
  }
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
    if(b.dataset.equipmentCustom){const id=b.dataset.equipmentCustom,t=TYPES[id],row=typeof chosen==='object'?chosen:t.loadouts.find(l=>l.id===chosen);loadoutEditor.open({type:id,row,onCancel:()=>model(id),onApply:next=>{chosen=next;model(id);return {ok:true};}});}
    else if(b.dataset.equipmentModel){chosen=null;model(b.dataset.equipmentModel);}
    else if(b.hasAttribute('data-equipment-back'))list();
    else if(b.dataset.equipmentPage!==undefined){page=Number(b.dataset.equipmentPage);list();}
    else if(b.dataset.equipmentSide){setSide(b.dataset.equipmentSide);country='';page=0;list();}
    else if(b.dataset.equipmentPlace){document.querySelector('#dialog').close();onDeploy(b.dataset.equipmentPlace,chosen);}
  });
  document.addEventListener('change',e=>{const key=e.target.id;if(key==='detail-loadout'){if(e.target.value!=='custom')chosen=e.target.value;model(detail);return;}
    if(!key.startsWith('catalog-')||key==='catalog-search')return;const v=e.target.value;if(key==='catalog-series'){series=v;country=category=period='';}if(key==='catalog-category')category=v;if(key==='catalog-country')country=v;if(key==='catalog-period')period=v;page=0;list();
  });
  document.addEventListener('input',e=>{if(e.target.id!=='catalog-search')return;query=e.target.value;page=0;clearTimeout(timer);timer=setTimeout(()=>{list();const input=document.querySelector('#catalog-search');input?.focus();},180);});
  document.querySelector('#dialog').addEventListener('close',()=>clearTimeout(timer));
  return {open(mode=false){deploy=mode;page=0;if(isWW2(getState())){series='ww2';country=category=period='';}else if(series==='ww2')series='modern';if(mode&&getBattleTheatre(getState())){country='';}list();},model(id){chosen=null;model(id);}};
}
